CREATE OR REPLACE VIEW stocktrans AS select "debtortrans"."transno" AS "transno","debtortrans"."type" AS "systype","debtortrans"."order_" AS "orderno","debtortrans"."debtorno" AS "debtorno","debtortrans"."debtorno" AS "dno","debtortrans"."branchcode" AS "branchcode","stockmoves"."stockid" AS "stockid","stockmoves"."loccode" AS "loccode","stockmoves"."trandate" AS "trandate","stockmoves"."stkmoveno" AS "stkmoveno","stockmoves"."orderlineref" AS "orderlineref","stockmoves"."qty" AS "qty",cast("stockmoves"."price" as decimal(10,2)) AS "price","stockmoves"."loccode" AS "fromstkloc","stockmaster"."image" AS "image","salesorders"."placedfrom" AS "placedfrom","salesorders"."enteredby" AS "enteredby",(select "salesorderdetails"."itemdesc" from "salesorderdetails" where "salesorderdetails"."orderno" = "debtortrans"."order_" and "salesorderdetails"."stkcode" = "stockmoves"."stockid" and "salesorderdetails"."orderlineno" = "stockmoves"."orderlineref") AS "itemdesc","stockmoves"."discountpercent" AS "discountpercent",cast(round(round("stockmoves"."price",2) * round("stockmoves"."discountpercent",4),2) as decimal(10,2)) AS "discount_per_unit",cast(round(round(cast("stockmoves"."price" as decimal(20,6)),2) - round(round(cast("stockmoves"."price" as decimal(20,6)),2) * round(cast("stockmoves"."discountpercent" as decimal(20,10)),4),2),2) as decimal(10,2)) AS "price_after_discount",cast(round(round(round(cast("stockmoves"."price" as decimal(20,6)),2) - round(round(cast("stockmoves"."price" as decimal(20,6)),2) * round(cast("stockmoves"."discountpercent" as decimal(20,10)),4),2),2) * cast("stockmoves"."qty" as decimal(20,6)),2) as decimal(10,2)) AS "discountedlinetotal","debtortrans"."ovamount" AS "ovamount","debtortrans"."ovgst" AS "ovgst","debtortrans"."ovfreight" AS "ovfreight","debtortrans"."ovdiscount" AS "ovdiscount","debtortrans"."salesperson" AS "salesperson","debtortrans"."inputdate" AS "inputdate",month("stockmoves"."trandate") AS "tranmnth",quarter("stockmoves"."trandate") AS "tranqtr",year("stockmoves"."trandate") AS "tranyear","stockmoves"."type" AS "type","salesman"."salesmanname" AS "salesmanname","debtortrans"."tpe" AS "salestype","custbranch"."brname" AS "brname","custbranch"."territory_id" AS "territory_id","territory"."territory_name" AS "territory_name","stockmoves"."standardcost" AS "standardcost",cast("stockmoves"."qty" * "stockmoves"."standardcost" as decimal(10,2)) AS "costtotal","stockmaster"."description" AS "description","stockmaster"."categoryid" AS "categoryid","stockmaster"."lineid" AS "lineid","custbranch"."store_location" AS "store_location","custbranch"."salesman" AS "branchsalesmancode","custbranch"."price_type" AS "discountgroup","suppliers"."suppname" AS "suppliername","suppliers"."supplierid" AS "supplierid","manufacturer"."name" AS "BRANDNAME" from (((((((((("stockmoves" join "debtortrans" on("stockmoves"."transno" = "debtortrans"."transno" and "stockmoves"."type" = "debtortrans"."type" and "stockmoves"."debtorno" = "debtortrans"."debtorno" and "stockmoves"."branchcode" = "debtortrans"."branchcode")) join "custbranch" on("custbranch"."debtorno" = "debtortrans"."debtorno" and "custbranch"."branchcode" = "debtortrans"."branchcode")) join "territory" on("territory"."territory_id" = "custbranch"."territory_id")) left join "salesorders" on("debtortrans"."order_" = "salesorders"."orderno")) left join "salesman" on("salesman"."salesmancode" = "debtortrans"."salesperson")) join "stockmaster" on("stockmaster"."stockid" = "stockmoves"."stockid")) left join "purchdata" on("purchdata"."stockid" = "stockmoves"."stockid")) left join "suppliers" on("purchdata"."supplierno" = "suppliers"."supplierid")) left join "product_to_manufacturer" on("product_to_manufacturer"."stockid" = "stockmoves"."stockid")) left join "manufacturer" on("manufacturer"."manufacturer_id" = "product_to_manufacturer"."manufacturer_id")) where true and NOT ("debtortrans"."debtorno" in (select "debtorsmaster"."debtorno" from "debtorsmaster" where "debtorsmaster"."typeid" = 10)) and ("stockmoves"."type" = 10 or "stockmoves"."type" = 11) and "stockmoves"."show_on_inv_crds" = 1 and ("stockmoves"."stockid"  not like 'SUAA%' and "stockmoves"."stockid"  not like 'SUAE%' or "stockmoves"."stockid" = 'SUAASU2002');
